1	import { all, get, run, saveDb } from './db.js';
2	
3	export interface Shelf {
4	  id: number;
5	  user_id: number;
6	  name: string;
7	  created_at: string;
8	}
9	
10	const MAX_SHELF_NAME_LENGTH = 50;
11	
12	export function getShelvesByUser(userId: number): Shelf[] {
13	  return all('SELECT * FROM shelves WHERE user_id = ? ORDER BY name', [userId]) as unknown as Shelf[];
14	}
15	
16	export function getShelfById(id: number): Shelf | undefined {
17	  return get('SELECT * FROM shelves WHERE id = ?', [id]) as unknown as Shelf | undefined;
18	}
19	
20	export function createShelf(userId: number, name: string): Shelf {
21	  const trimmed = name.trim();
22	  if (trimmed.length === 0 || trimmed.length > MAX_SHELF_NAME_LENGTH) {
23	    throw new Error(`Shelf name must be between 1 and ${MAX_SHELF_NAME_LENGTH} characters`);
24	  }
25	
26	  const result = run('INSERT INTO shelves (user_id, name) VALUES (?, ?)', [userId, trimmed]);
27	  saveDb();
28	  return getShelfById(result.lastInsertRowid)!;
29	}
30	
31	export function deleteShelf(id: number, userId: number): boolean {
32	  const result = run('DELETE FROM shelves WHERE id = ? AND user_id = ?', [id, userId]);
33	  if (result.changes > 0) {
34	    saveDb();
35	  }
36	  return result.changes > 0;
37	}
